using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseSeamCorrection {
 class Edge {public int a,b,c;}
 static string Key(Vector3 p){return Mathf.RoundToInt(p.x*100000)+","+Mathf.RoundToInt(p.y*100000)+","+Mathf.RoundToInt(p.z*100000);}
 static Texture2D Read(string path){var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(path));return t;}
 public static void Run(){
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab"));go.GetComponent<Animator>().enabled=false;go.GetComponent<LODGroup>().ForceLOD(0);RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(go);
 NurseVisualOptimization.Render(go,"SeamBaseline",0,true,true);
 var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var m=r.sharedMesh;var p=m.vertices.Select(r.transform.TransformPoint).ToArray();var uv=m.uv;var n=m.normals;var t=m.tangents;var tri=m.GetTriangles(0);var albedo=Read(NurseVisualOptimization.Folder+"/Atlas_Albedo.png");var normal=Read(NurseVisualOptimization.Folder+"/Atlas_Normal.png");int size=albedo.width;var colors=albedo.GetPixels();var normals=normal.GetPixels();var colorSum=new Color[size*size];var normalSum=new Vector3[size*size];var weight=new float[size*size];var edges=new Dictionary<string,List<Edge>>();
 Func<Vector3,bool> face=v=>v.y>1.64f&&v.y<1.715f&&Mathf.Abs(v.x)<.075f&&v.z>.035f;
 for(int k=0;k<tri.Length;k+=3)for(int e=0;e<3;e++){int a=tri[k+e],b=tri[k+(e+1)%3],c=tri[k+(e+2)%3];if(!face(p[a])||!face(p[b]))continue;string ka=Key(p[a]),kb=Key(p[b]);if(ka==kb)continue;if(String.CompareOrdinal(ka,kb)>0){int z=a;a=b;b=z;string q=ka;ka=kb;kb=q;}string key=ka+"|"+kb;if(!edges.ContainsKey(key))edges[key]=new List<Edge>();edges[key].Add(new Edge{a=a,b=b,c=c});}
 Func<Edge,float,Vector3> N=(e,f)=>Vector3.Lerp(n[e.a],n[e.b],f).normalized;
 Func<Edge,float,Vector3> T=(e,f)=>{var v=Vector4.Lerp(t[e.a],t[e.b],f);return new Vector3(v.x,v.y,v.z).normalized;};
 Func<Edge,float,Vector3> B=(e,f)=>Vector3.Cross(N(e,f),T(e,f))*Mathf.Sign(Mathf.Lerp(t[e.a].w,t[e.b].w,f));
 int groups=0,samples=0;double before=0,after=0;
 foreach(var entries in edges.Values){var pair=entries.GroupBy(e=>uv[e.a].ToString("F6")+uv[e.b].ToString("F6")).Select(g=>g.First()).ToArray();if(pair.Length!=2)continue;var first=pair[0];if(Vector2.Distance(uv[first.a],uv[pair[1].a])<.002f&&Vector2.Distance(uv[first.b],uv[pair[1].b])<.002f)continue;groups++;int steps=Mathf.Max(2,Mathf.CeilToInt(pair.Max(e=>Vector2.Distance(uv[e.a],uv[e.b]))*size*2));
 for(int s=0;s<=steps;s++){float f=(float)s/steps;var cs=new Color[2];var ws=new Vector3[2];for(int j=0;j<2;j++){var e=pair[j];var q=Vector2.Lerp(uv[e.a],uv[e.b],f);var midpoint=(uv[e.a]+uv[e.b])*.5f;var direction=(uv[e.c]-midpoint).normalized;var inside=q+direction*(2f/size);cs[j]=albedo.GetPixelBilinear(inside.x,inside.y);var v=normal.GetPixelBilinear(inside.x,inside.y);ws[j]=(T(e,f)*(v.r*2-1)+B(e,f)*(v.g*2-1)+N(e,f)*(v.b*2-1)).normalized;}var commonColor=(cs[0]+cs[1])*.5f;var commonNormal=(ws[0]+ws[1]).normalized;before+=Vector3.Angle(ws[0],ws[1]);samples++;
 foreach(var e in pair){var q=Vector2.Lerp(uv[e.a],uv[e.b],f)*size;var target=new Vector3(Vector3.Dot(commonNormal,T(e,f)),Vector3.Dot(commonNormal,B(e,f)),Vector3.Dot(commonNormal,N(e,f))).normalized;int cx=Mathf.FloorToInt(q.x),cy=Mathf.FloorToInt(q.y);for(int y=cy-3;y<=cy+3;y++)for(int x=cx-3;x<=cx+3;x++){if(x<0||y<0||x>=size||y>=size)continue;float d=Vector2.Distance(new Vector2(x+.5f,y+.5f),q);if(d>=3)continue;float amount=1-Mathf.SmoothStep(0,1,d/3);int i=y*size+x;colorSum[i]+=commonColor*amount;normalSum[i]+=target*amount;weight[i]+=amount;}}
 }}
 int changed=0;for(int i=0;i<weight.Length;i++)if(weight[i]>0){float a=Mathf.Clamp01(weight[i]);colors[i]=Color.Lerp(colors[i],colorSum[i]/weight[i],a);var old=new Vector3(normals[i].r*2-1,normals[i].g*2-1,normals[i].b*2-1).normalized;var v=Vector3.Lerp(old,normalSum[i].normalized,a).normalized;normals[i]=new Color(v.x*.5f+.5f,v.y*.5f+.5f,v.z*.5f+.5f,1);changed++;}
 string folder="Assets/EntityStudioGenerated/NurseSeamCandidate";Directory.CreateDirectory(folder);foreach(bool data in new[]{false,true}){string source=NurseVisualOptimization.Folder+(data?"/Atlas_Normal.png":"/Atlas_Albedo.png");string path=folder+(data?"/Normal.png":"/Albedo.png");var image=new Texture2D(size,size,TextureFormat.RGBA32,false,data);image.SetPixels(data?normals:colors);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());File.Copy(source+".meta",path+".meta",true);var meta=File.ReadAllText(path+".meta");meta=System.Text.RegularExpressions.Regex.Replace(meta,"guid: [a-f0-9]{32}","guid: "+(data?"50cf96510aaa4b4ea2e65c4cf567accc":"50cf96510aaa4b4ea2e65c4cf567addd"));File.WriteAllText(path+".meta",meta);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);}
 foreach(var renderer in go.GetComponentsInChildren<SkinnedMeshRenderer>(true))renderer.sharedMaterials=renderer.sharedMaterials.Select(old=>{var material=new Material(old);if(material.HasProperty("_Albedo"))material.SetTexture("_Albedo",AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"/Albedo.png"));if(material.HasProperty("_Normal"))material.SetTexture("_Normal",AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"/Normal.png"));return material;}).ToArray();NurseVisualOptimization.Render(go,"SeamCandidate",0,true,true);File.WriteAllText(NurseVisualOptimization.Out+"/seam-correction-candidate.txt","Candidate only. Matched physical UV edges="+groups+" edge samples="+samples+" mean inward source world-normal disagreement="+(before/Math.Max(1,samples))+" degrees. Modified texture texels="+changed+" with 3px feather/gutter. No mesh, rig, collider or installed asset changes. Requires rendered visual review.");
 }
}
